import { ROLES, CONFIGURABLE_ROLES, defaultRoleCounts, roleCounts, validateRoleCounts, teamOf, validateName, maxMafia, assignRoles, passwordHash, suggestedWinner, eliminatePlayer, canGuessPolice, finalizeVictory, beginVillageFinale, resolveFinalGuess,migrateGame,validateManualAssignments,assignManualRoles} from './engine.mjs';
const $ = s => document.querySelector(s), bn = n => Number(n).toLocaleString(language !== 'bn' ? 'en-US' : 'bn-BD'), esc = s => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const paths = { mask: 'M3 7c6 3 12 3 18 0l-2 9c-3 4-5 3-7 1-2 2-4 3-7-1L3 7Zm3 4 4 1-2 2Zm12 0-4 1 2 2Z', arrow: 'M5 12h14m-5-5 5 5-5 5', plus: 'M12 5v14M5 12h14', person: 'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-2a8 8 0 0 1 16 0v2', people: 'M16 21v-2a6 6 0 0 0-12 0v2M14 3a4 4 0 0 1 0 8m6 10v-2a6 6 0 0 0-3-5M14 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z', shield: 'm12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Zm-3 9 2 2 4-4', heart: 'M12 20 3 11C-2 3 8-1 12 6c4-7 14-3 9 5l-9 9Z', lock: 'M6 10h12v11H6V10Zm3 0V6a3 3 0 0 1 6 0v4m-3 4v3', moon: 'M20 15A9 9 0 0 1 9 4 9 9 0 1 0 20 15Z', home: 'm3 11 9-8 9 8M5 9v12h14V9M9 21v-7h6v7', book: 'M4 3h7l1 2 1-2h7v17h-7l-1 1-1-1H4V3Zm8 2v16', check: 'm5 12 4 4L19 6', close: 'm6 6 12 12M6 18 18 6', edit: 'm4 16 12-12 4 4L8 20H4v-4Zm10-10 4 4', trash: 'M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7', eye: 'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z', back: 'M19 12H5m5-5-5 5 5 5', spark: 'm12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z', trophy: 'M8 3h8v8a4 4 0 0 1-8 0V3Zm0 2H3v3a5 5 0 0 0 5 5m8-8h5v3a5 5 0 0 1-5 5m-4 0v7m-5 1h10', play: 'm9 5 11 7-11 7V5', logout: 'M10 4H4v16h6m4-13 5 5-5 5m-5-5h14', wifi: 'M3 8a15 15 0 0 1 18 0M6 12a10 10 0 0 1 12 0m-9 4a5 5 0 0 1 6 0m-3 4h.01M3 3l18 18' };
const icon = (n, cls = '') => `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n] || paths.spark}"/></svg>`;
const heroQuotes={bn:nextQuote('bn'),en:nextQuote('en'),classic:nextQuote('classic')};let historyDeck=shuffledHistory();
const theme='light';let disposeSeatSort=null;
const KEY = 'mafia.game.v1'; let game = null, screen = 'home', shown = false, menu = false, busy = false, wake, expiredSound;
try { game = JSON.parse(localStorage.getItem(KEY)) } catch { localStorage.removeItem(KEY) }
if (game) { migrateGame(game);game.hostProfile??=saveProfile(readProfile());if(game.players.some(p=>!Number.isInteger(p.characterIndex)))assignCharacterIndexes(game.players,game.revealOrder);game.assignmentMode??='AUTO';game.manualRoles=Object.assign(Object.create(null),game.manualRoles||{});game.revealOrder??=game.players.map((_,i)=>i);game.timer ??= newTimer(); game.players?.forEach(p => { p.score ??= 0; p.plan ??= '' }); }
function save() { try { localStorage.setItem(KEY, JSON.stringify(game)) } catch { toast('সেভ করা যাচ্ছে না। স্টোরেজে জায়গা খালি করো।') } }
function toast(t) {sound('notice'); $('#toast').textContent = t; $('#toast').classList.add('visible'); setTimeout(() => $('#toast').classList.remove('visible'), 2600) }
function route(s) { if(s==='over')sound('win'); $('#overlay').innerHTML = ''; screen = s; shown = false; menu = false; render(); window.scrollTo(0, 0); if (game && s !== 'home' && s !== 'rules' && !wake) navigator.wakeLock?.request('screen').then(w => { wake = w; w.addEventListener('release', () => wake = null) }).catch(() => { }); }
function setup() { heroQuotes[language]=nextQuote(language);historyDeck=shuffledHistory(); game = { id: crypto.randomUUID(), hostProfile:saveProfile(readProfile()), status: 'names', names: [], mafiaCount: 1, roleCounts: null, assignmentMode:'AUTO',manualRoles:Object.create(null),startName:null,revealOrder:null,awardsApplied:false,pendingVictory:null, finalGuess: null, currentRound: 0, revealIndex: 0, players: [], winner: null, lastSuggestion: null, timer: newTimer(), createdAt: new Date().toISOString() }; save(); route('names') }
function modal(title, description, buttons) { $('#overlay').innerHTML = `<div class="scrim"><section class="dialog" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="dialog-mark">${icon('moon')}</div><h2>${esc(title)}</h2><p>${esc(description)}</p><div class="dialog-actions">${buttons.map((b, i) => `<button class="btn ${b.style || 'secondary'}" data-modal="${i}">${esc(b.label)}</button>`).join('')}</div></section></div>`; document.querySelectorAll('[data-modal]').forEach(el => el.onclick = () => { $('#overlay').innerHTML = ''; buttons[Number(el.dataset.modal)].action?.() }); localize($('#overlay')); $('[data-modal]')?.focus(); }
function confirm(title, description, action, label = 'হ্যাঁ, নিশ্চিত') { modal(title, description, [{ label, style: 'primary', action }, { label: 'বাতিল' }]) }
const badge = (r) => `<span class="badge ${ROLES[r].color}">${icon(ROLES[r].icon)} ${roleName(r)}</span>`;
const button = (text, action, cls = 'primary', ico = 'arrow', extra = '') => `<button class="btn ${cls}" data-action="${action}" ${extra.includes('type=') ? '' : 'type="button"'} ${extra}>${esc(text)}${ico ? icon(ico) : ''}</button>`;
const heading = (k, t, d) => `<div class="eyebrow">${k}</div><h1>${t}</h1><p class="lede">${d}</p>`;
function home(){const world=UNIVERSES[language],q=heroQuotes[language];return `<section class="hero minimal-hero"><div class="hero-copy"><span class="eyebrow">${world.universeName}</span><h1>${tr('বন্ধুদের সঙ্গে Mafia','Mafia. Among friends.')}</h1><p>${tr('গোপন পরিচয়, আলোচনা ও ভোট। একজন হোস্ট খেলা পরিচালনা করেন।','Secret roles, discussion, and a vote. One host runs the table.')}</p><div class="hero-buttons">${button(tr('নতুন খেলা','New game'),'new','primary','plus')}${game?button(tr('চালিয়ে যাও','Continue'),'resume','secondary','play'):''}<a class="btn secondary" href="room.html?lang=${language}">${tr('আলাদা ফোনে খেলো','Play online')}</a></div></div><div class="hero-art court-cover"><img src="assets/${language}/cover.png" alt="${world.universeName}" width="1672" height="941"></div></section><blockquote class="literary-quote"><p>${q.text}</p><cite>${q.credit}</cite></blockquote><details class="cast-drawer"><summary>${tr('চরিত্রগুলো দেখুন','Meet the characters')}</summary><div class="cast-grid">${Object.entries(ROLES).filter(([r])=>r in world.roles).map(([role,r])=>`<article class="cast-card">${roleAvatar(role)}<h3>${roleName(role)}</h3><small>${characterFor(role,language).name}</small></article>`).join('')}</div></details>`;}

function progress() { const steps = ['নাম লেখো', 'রোল ঠিক করো', 'লক করো']; const n = ['names', 'config', 'password'].indexOf(screen); return `<div class="progress">${steps.map((s, i) => `<span class="${i <= n ? 'active' : ''}"><b>${i < n ? icon('check') : bn(i + 1)}</b>${s}</span>`).join('<i></i>')}</div>` }
function names(){return `${progress()}${heading(tr('প্রথম ধাপ · আসন সাজাও','STEP ONE · ARRANGE THE SEATS'),tr('কে কোথায় বসেছে?','Who’s sitting where?'),tr('হোস্টের নাম বাদ রাখো। তালিকা মেনে ফোন চালাও: ১ → ২ → ৩ → ৪।','Exclude the host. Pass the phone in list order: 1 → 2 → 3 → 4.'))}<form id="name-form" class="name-form"><div class="input-wrap">${icon('person')}<input id="player-name" placeholder="${tr('প্লেয়ারের নাম','Player name')}" autocomplete="off" maxlength="40" aria-label="${tr('প্লেয়ারের নাম','Player name')}"></div>${button('যোগ করো','add','primary','plus','type="submit"')}</form><p id="form-error" class="error" role="alert"></p><div class="list-heading"><span>${tr('আসনের ক্রম','Player sequence')}</span><span>${bn(game.names.length)} / ${bn(20)}</span></div><p class="seat-hint" id="seat-sort-help">${tr('বাঁয়ের দানা ধরে টানো, পছন্দমতো আসন আনো।','Drag the grip to move a player between seats.')}<span class="sr-only">${tr('কী-বোর্ডে স্পেস দিয়ে ধরো, তির দিয়ে সরো; আবার স্পেসে ছাড়ো, এসকেপে ফেরো।','Keyboard: Space to lift, arrow keys to move, Space to drop, Escape to cancel.')}</span></p><div class="sr-only" id="seat-announcement" role="status" aria-live="polite" aria-atomic="true"></div><div class="name-list sortable-seats" role="list" aria-label="${tr('আসনের তালিকা','Seating order')}">${game.names.length?game.names.map((name,i)=>`<div class="name-row seat-row" role="listitem" data-sort-name="${esc(name)}"><button type="button" class="drag-handle" data-drag-handle aria-label="${tr('আসন সরাও: ','Reorder: ')+esc(name)}" aria-describedby="seat-sort-help" aria-pressed="false">${gripIcon()}</button><span class="seat-initial" aria-hidden="true">${esc(name.charAt(0))}</span><div class="seat-name"><span class="player-name">${esc(name)}</span><small class="seat-number" aria-label="${tr('আসন','Seat')}">${bn(i+1)}</small></div><button class="icon-btn" data-edit="${i}" aria-label="${tr('নাম বদলাও: ','Edit name: ')+esc(name)}">${icon('edit')}</button><button class="icon-btn" data-remove="${i}" aria-label="${tr('নাম মুছো: ','Remove name: ')+esc(name)}">${icon('trash')}</button></div>`).join(''):''}</div>${game.names.length?seatingPreview():`<div class="empty">${icon('people')}<h3>${tr('প্রথম নামটি লেখো','Add your first player')}</h3><p>${tr('৫ থেকে ২০ জন খেলতে পারবে।','For 5–20 players.')}</p></div>`}<div class="form-bottom"><small>${game.names.length<5?tr('কমপক্ষে ৫ জন লাগবে','At least 5 players required'):tr('সবাই ঠিক আসনে?','Everyone in the right seat?')}</small>${button('পরবর্তী','to-config','primary','arrow',game.names.length<5?'disabled':'')}</div>`}
function config(){game.roleCounts??=defaultRoleCounts(game.names.length);const counts=roleCounts(game.names.length,game.roleCounts),error=setupError();return `${progress()}${heading(tr('দ্বিতীয় ধাপ · পরিচয় বণ্টন','STEP TWO · DEAL THE IDENTITIES'),tr('রোল বেছে নাও','Choose your roles'),tr('প্রতি রোলের সংখ্যা ঠিক করো। ইচ্ছেমতো ঐচ্ছিক চরিত্র যোগ করো।','Set the number of each role and add optional characters.'))}${assignmentToggle()}<div class="config-total">${icon('people')}<div><small>${tr('মোট প্লেয়ার','Players')}</small><strong>${bn(game.names.length)}</strong></div>${button(tr('আসন বদলাও','Edit seats'),'back-names','text','edit')}</div><div class="cast-builder">${CONFIGURABLE_ROLES.filter(r=>r in UNIVERSES[language].roles).map(key=>{const count=game.roleCounts[key];return `<article class="role-config-row">${roleAvatar(key)}<div class="role-config-copy"><h3>${roleName(key)} ${ROLES[key].optional?`<span class="optional-tag">${tr('ঐচ্ছিক','OPTIONAL')}</span>`:''}</h3><p>${roleTagline(key)}</p><small>${teamName(ROLES[key].team)}</small></div><div class="role-count-control"><button type="button" data-role-count="${key}" data-delta="-1" ${count<=(key==='MAFIA'?1:0)?'disabled':''} aria-label="${tr('কমাও: ','Decrease: ')+roleName(key)}">−</button><output aria-label="${tr('সংখ্যা: ','Count: ')+roleName(key)}">${bn(count)}</output><button type="button" data-role-count="${key}" data-delta="1" ${count>=game.names.length?'disabled':''} aria-label="${tr('বাড়াও: ','Increase: ')+roleName(key)}">+</button></div></article>`}).join('')}<div class="villager-fill">${roleAvatar('VILLAGER')}<div><strong>${tr('বাকি সবাই প্রজা','Remaining players are villagers')}</strong><small>${tr('অন্য রোলের সংখ্যা অনুযায়ী','Calculated from the roles above')}</small></div><b>${bn(Math.max(0,counts.VILLAGER))}</b></div></div>${game.assignmentMode==='MANUAL'?manualAssignmentPanel(counts):''}<p class="config-error ${error?'error':''}" role="status">${error?roleConfigError(error):tr('রোল বণ্টনের জন্য প্রস্তুত।','Ready to deal the roles.')}</p>${seatingPreview()}${scoringLegend()}${button(tr('পরবর্তী','Continue'),'to-password','primary wide','arrow',error?'disabled':'')}`}
function passwordField(id,label){const legacy=id==='unlock'&&game.pinFormat!=='numeric-4';if(legacy)return `<label class="field-label" for="${id}">${tr('আগের খেলার পাসওয়ার্ড','Saved game password')}</label><div class="input-wrap"><input id="${id}" type="password" autocomplete="current-password" required></div>`;return `<label class="field-label" for="${id}">${label}</label><div class="pin-entry"><input id="${id}" data-pin type="password" inputmode="numeric" pattern="[0-9]{4}" minlength="4" maxlength="4" autocomplete="off" aria-label="${esc(label)}" aria-describedby="${id}-hint" required><div class="pin-cells" aria-hidden="true">${'<span class="pin-cell"></span>'.repeat(4)}</div></div><small id="${id}-hint" class="pin-hint">${tr('ঠিক চারটি সংখ্যা','Exactly four digits')}</small>`;}

function password() { return `${progress()}${heading(tr('তৃতীয় ধাপ · শুধু হোস্ট জানবে','STEP THREE · HOST EYES ONLY'),tr('হোস্টের চার সংখ্যার চাবি','Your four-digit host PIN'),tr('চারটি সংখ্যা দাও, গোপন রাখো। এই পিনে হোস্টের পাতা খোলো।','Choose four numbers and keep them private. Use this PIN to open the host panel.'))}<form id="password-form" class="panel password-panel">${passwordField('password', tr('চার সংখ্যার পিন','4-digit host PIN'))}${passwordField('repeat', tr('পিন আবার লেখো','Confirm PIN'))}<p class="notice">${icon('shield')} এই পাসওয়ার্ড রিসেট করা যাবে না। মনে রাখো।</p><p id="form-error" class="error" role="alert"></p>${button('লক করে রোল বণ্টন করো', 'distribute', 'primary wide', 'lock', 'type="submit"')}<button class="btn text wide" type="button" data-action="back-config">← রোল বদলাও</button></form>` }
function reveal() { const p=game.players[game.revealOrder?.[game.revealIndex]??game.revealIndex],r=ROLES[p.role],from=game.revealIndex?game.players[game.revealOrder[game.revealIndex-1]].name:(game.hostProfile?.name||tr('হোস্ট','Host')); return `<section class="secret-screen"><p class="handoff-label"><span data-player-name>${esc(from)}</span> → <span data-player-name>${esc(p.name)}</span> · ${tr('তালিকার পরের জনের হাতে','NEXT IN THE LIST')}</p>${shown ? `<span class="pill">${icon('lock')} এই পরিচয় শুধু তোমার</span><div class="reveal-portrait ${r.color}">${roleAvatar(p.role,'',p.characterIndex)}</div><p class="eyebrow">${esc(p.name)}, তুমি</p><h1 class="${r.color}">${roleName(p.role)}</h1><h2 class="identity-name">${characterFor(p.role,language,p.characterIndex).name}</h2><details class="identity-history"><summary>${tr('চরিত্রের কথা','About this character')}</summary><p>${characterFor(p.role,language,p.characterIndex).history}</p></details><p class="lede">${UNIVERSES[language].roles[p.role].description}</p><div class="secret-tip">পরিচয় মনে রাখো। কাউকে দেখিও না।</div>${button(game.revealIndex === game.players.length - 1 ? tr('শেষ — হোস্টকে ফোন দাও','Return to the host') : tr('পরের জনকে দাও → ','Pass to → ')+game.players[game.revealOrder[game.revealIndex+1]].name, 'next-player', 'primary wide')}` : `<span class="pill">${icon('lock')} গোপন রোল বণ্টন</span><div class="mystery-card">${icon('mask')}<span>?</span></div><h1>${esc(p.name)},<br>এখন তোমার পালা</h1><p class="lede">শুধু তুমি স্ক্রিন দেখবে।<br>অন্যরা চোখ সরিয়ে রাখো।</p>${button('আমি ' + p.name + ' — রোল দেখাও', 'reveal', 'primary wide', 'eye')}`}</section>` }
function unlock() { return `<section class="unlock-screen"><span class="role-orb">${icon('lock')}</span>${heading('শহরের নিয়ন্ত্রণ ফেরত নাও', 'শুধু হোস্টের জন্য', 'চার সংখ্যার পিন দিয়ে হোস্ট পেজ খোলো।')}<form id="unlock-form">${passwordField('unlock', tr('হোস্ট পিন','Host PIN'))}<p id="form-error" class="error" role="alert"></p>${button('আনলক', 'unlock', 'primary wide', 'lock', 'type="submit"')}</form>${button('গেম বাতিল করো', 'cancel', 'text', '')}</section>` }
function playerRows(over = false) { return `<div class="host-list">${game.players.map((p, i) => `<div class="host-row ${p.isAlive ? '' : 'dead'}">${roleAvatar(p.role, 'player-portrait',p.characterIndex)}<div class="player-info"><strong>${esc(p.name)}</strong><div>${badge(p.role)}<small>${characterFor(p.role,language,p.characterIndex).name}</small>${!p.isAlive ? `<small>${tr('মৃত — রাউন্ড ', 'Out — round ') + bn(p.diedInRound)}${p.deathCause ? ' · ' + (p.deathCause === 'NIGHT' ? tr('রাতে', 'night') : tr('ভোটে', 'vote')) : ''}</small>` : over ? `<small>${tr('জীবিত', 'Alive')}</small>` : ''}</div>${!over && p.role === 'ASTROLOGER' ? `<small class="immunity-note">${tr('রাতে ইমিউন · ভোটে বাদ যাবে', 'Night immune · can be voted out')}</small>` : ''}</div>${over ? `<div class="result-points"><strong>${bn(scoreOf(p))}</strong><small>+${bn(p.winPoints || 0)} ${tr('জয়ের পয়েন্ট', 'win points')}</small></div>` : `<button class="${p.isAlive ? 'icon-btn eliminate' : 'restore'}" data-player="${i}" aria-label="${esc(p.name)} ${p.isAlive ? 'বাদ দাও' : 'ফিরিয়ে আনো'}">${p.isAlive ? icon('close') : 'ফিরিয়ে আনো'}</button>`}</div>`).join('')}</div>` }
function host() { const alive = game.players.filter(p => p.isAlive), m = alive.filter(p => teamOf(p.role) === 'MAFIA').length, w = suggestedWinner(game.players); return `<div class="host-heading"><div>${heading(tr('হোস্টের পাতা','HOST PANEL'), game.currentRound ? 'রাউন্ড ' + bn(game.currentRound) : tr('সবাই প্রস্তুত','Everyone is ready'), 'গোপন পরিচয় তোমার কাছেই নিরাপদ।')}</div><button class="icon-btn" data-action="menu" aria-label="গেম মেনু">•••</button>${menu ? `<div class="dropdown">${button('পেজ লক করো', 'lock', 'text', 'lock')}${button('গেম শেষ করো', 'manual-end', 'text', 'trophy')}${button('গেম বাতিল করো', 'cancel', 'text', 'close')}</div>` : ''}</div><div class="stats"><div><i class="green-dot"></i><strong>${bn(alive.length)}</strong><small>জীবিত</small></div><div><strong>${bn(game.players.length - alive.length)}</strong><small>মৃত</small></div><div class="red">${icon('mask')}<strong>${bn(m)}</strong><small>${tr('জীবিত ঘাতক দল', 'Mafia team alive')}</small></div></div><section class="single-host-card">${roleAvatar('HOST')}<div><strong>${characterFor('HOST',language).name}</strong><p>${tr('হোস্ট খেলোয়াড় নন। সম্পূর্ণ আসরে এক পয়েন্ট।','The host is not a player. Completed game: +1 point.')}</p></div></section>${hostTools()}${w ? `<div class="win-banner">গেম শেষের শর্ত পূরণ হয়েছে ${button('গেম শেষ করো', 'suggest-end', 'text', 'arrow')}</div>` : ''}<div class="list-heading"><span>${tr('সব প্লেয়ার','Players')}</span><span>${game.currentRound ? 'রাউন্ড চলছে' : 'রাউন্ড শুরু হয়নি'}</span></div>${playerRows()}<div class="sticky-action">${button('রাউন্ড ' + bn(game.currentRound + 1) + ' স্টার্ট', 'round', 'primary wide', 'moon')}<small>রাতের ঘটনা ও ভোট হোস্ট মুখে পরিচালনা করবে।</small></div>` }
function over() { const guess = game.finalGuess, target = guess?.targetId ? game.players.find(p => p.id === guess.targetId) : null; return `<div class="over-heading"><div class="role-orb huge ${game.winner === 'MAFIA' ? 'red' : 'green'}">${icon('trophy')}</div><span class="eyebrow">${tr('ক্ষমতার খেলায় চূড়ান্ত ফল', 'THE FINAL REVEAL')}</span><h1>${winnerName(game.winner)} ${tr('জয়!', 'win!')}</h1><p class="lede">${bn(game.currentRound)} ${tr('রাউন্ডের সন্দেহ ও চক্রান্ত।', 'rounds of suspicion and conspiracy.')}</p></div>${guess ? `<div class="finale-result ${guess.correct ? 'twist-win' : ''}">${icon(guess.correct ? 'spark' : 'shield')}<div><strong>${guess.correct ? tr('শেষ আন্দাজে বাজিমাত!', 'The last guess stole the game!') : tr('প্রজাদের জয় টিকে গেল!', 'The village kept its victory!')}</strong><p>${guess.skipped ? tr('ঘাতক দল শেষ আন্দাজের সুযোগ নেয়নি।', 'The Mafia skipped their final guess.') : tr('ঘাতকদের আন্দাজ: ', 'The Mafia guessed: ') + esc(target?.name || '') + ' · ' + (guess.correct ? tr('সেনাপতি! তাই ঘাতকদের জয়।', 'Police! The Mafia win instead.') : tr('সেনাপতি নয়।', 'Not police.'))}</p></div></div>` : ''}<div class="points-awarded">${icon('check')} ${tr('জয়ের পয়েন্ট অটো যোগ হয়েছে—একবারই।', 'Victory points added automatically — exactly once.')}</div>${scoringLegend()}<div class="result-ranking">${button(tr('স্কোর ও র‍্যাঙ্কিং', 'Scores & rankings'), 'scores', 'secondary wide', 'trophy')}</div>${playerRows(true)}<div class="end-actions">${button('নতুন গেম', 'fresh', 'primary wide', 'plus')}${button('একই নাম নিয়ে নতুন গেম', 'rematch', 'secondary wide', 'people')}${button('হোম', 'home', 'text wide', 'home')}</div>` }
function rules(){return `${heading(tr('খেলার নিয়ম','HOW TO PLAY'),UNIVERSES[language].title,tr('হোস্ট পরিচালনা করবেন; সিদ্ধান্ত নেবে সবাই।','The host guides the game. Everyone helps decide.'))}<div class="rules-list">${[[tr('আসন ও ফোনের ক্রম','Seats and phone order'),tr('তালিকায় নাম সাজান। প্রয়োজনে টেনে ক্রম বদলান। ফোন যাবে ১ → ২ → ৩ → ৪ ক্রমে।','Arrange the list with the drag grips. Pass the phone in sequence: 1 → 2 → 3 → 4.')],[tr('রোল বণ্টন','Role assignment'),tr('হোস্ট পরিচয় বেছে দিতে পারেন অথবা স্বয়ংক্রিয় বণ্টন করতে পারেন। বেছে দেওয়া পরিচয়ের সংখ্যা ঠিক থাকতে হবে।','Choose random roles or let the host assign them. Every role count is configurable. Manual assignments must match the chosen counts.')],[tr('গোপন পরিচয়','Private identities'),tr('খেলোয়াড় শুধু নিজের পরিচয় দেখবেন। হোস্টের নিয়ন্ত্রণ খুলতে পিন লাগবে।','Each player sees only their own role. The host panel requires the host password.')],[tr('রাত ও ভোট','Night and voting'),tr('হোস্ট রাতের আক্রমণ, চিকিৎসা, রক্ষা ও তদন্ত পরিচালনা করবেন। আলোচনা শেষে ভোট দিন। গণককে রাতে মারা যায় না, তবে ভোট দিয়ে বাদ দেওয়া যায়।',language==='classic'?'The host resolves Mafia attacks, Doctor saves, and Police investigations. Discuss and vote to eliminate suspects.':'The host narrates Mafia attacks, Doctor and Spy protection, and Police investigations. The Consigliere cannot be killed at night, but can be voted out.')],[tr('বিশ্বাসঘাতকতা','Betrayal'),tr('বিশ্বাসঘাতক ঘাতকদের সাহায্য করেন। প্রকৃত ঘাতকেরা সবাই বাদ পড়লে প্রজাদের জয়ের সুযোগ আসে।','The Betrayer helps the Mafia. When all actual Mafia are out, the village gets its victory chance.')],[tr('শেষ আন্দাজ','The final guess'),tr('প্রজাদের জয়ের আগে ঘাতকেরা একবার সেনাপতির পরিচয় অনুমান করতে পারেন। সঠিক হলে ঘাতকেরা জিতবেন। ভুল হলে বা সুযোগ ছেড়ে দিলে প্রজারা জিতবেন। বাদ পড়া সেনাপতিকেও অনুমান করা যায়।','Before a village victory, the Mafia get one shared Police guess. A correct guess flips the winner; a wrong or skipped guess preserves the village win. Any Police player counts, alive or eliminated.')],[tr('পয়েন্ট','Points'),tr('ঘাতকের জয়ে ঘাতকের ৩ ও বিশ্বাসঘাতকের ২ পয়েন্ট। প্রজাদের জয়ে বৈদ্য ও সেনাপতির ২, অন্য প্রজাদের ১। সম্পূর্ণ খেলায় হোস্টের ১ পয়েন্ট। খেলা ছেড়ে যাওয়া খেলোয়াড় জয়ের পয়েন্ট পাবেন না।','A Mafia win gives actual Mafia 3 and Betrayers 2. The non-player host earns 1 for a completed game. A village win gives Doctors and Police 2 each, other villagers 1 each. These awards add to host points exactly once.')],[tr('পরের খেলা','The next game'),tr('হোস্ট দায়িত্ব হস্তান্তর না করলে একই থাকবেন। পরের খেলায় ফোন আবার তালিকার প্রথম জন থেকে যাবে।','The host stays in charge. A rematch follows the player list from 1 onward. Reorder the list before dealing if needed.')]].map((r,i)=>`<article><b>${bn(i+1)}</b><div><h3>${r[0]}</h3><p>${r[1]}</p></div></article>`).join('')}</div><div class="role-rule-details">${Object.keys(UNIVERSES[language].roles).map(role=>`<details><summary>${roleName(role)}</summary><p>${UNIVERSES[language].roles[role].description}</p></details>`).join('')}</div>${button(tr('খেলা শুরু করো','Start a game'),'new','primary','plus')}`}
function render() {disposeSeatSort?.();disposeSeatSort=null; document.documentElement.dataset.theme=theme;document.documentElement.dataset.universe=language; document.documentElement.lang = language==='bn'?'bn':'en';document.querySelector('link[rel=manifest]').href=language!=='bn'?'manifest-en.webmanifest':'manifest.webmanifest'; document.title = UNIVERSES[language].title+' · '+UNIVERSES[language].subtitle; const palette=getComputedStyle(document.documentElement).getPropertyValue('--bg').trim();document.querySelector('meta[name="theme-color"]').content=palette;window.Android?.setPalette?.(palette,true); const privateScreen = ['reveal', 'unlock', 'last-chance'].includes(screen); document.body.classList.toggle('private-mode', privateScreen); window.Android?.setSecure(screen === 'host' || (screen === 'reveal' && shown)); window.Android?.setPlaying(!['home', 'rules', 'over'].includes(screen)); $('#app').innerHTML = `<aside class="sidebar"><a class="brand" href="#" data-action="home"><span class="brand-icon">${icon('mask')}</span><span>${UNIVERSES[language].title}<small>${UNIVERSES[language].subtitle}</small></span></a><div class="nav-label">${tr('তোমার দরবার','YOUR TABLE')}</div><nav>${button('হোম', 'home', screen === 'home' ? 'nav-item selected' : 'nav-item', 'home')}${button('কীভাবে খেলবে', 'rules', screen === 'rules' ? 'nav-item selected' : 'nav-item', 'book')}${game ? button('চলমান গেম', 'resume', !['home', 'rules'].includes(screen) ? 'nav-item selected' : 'nav-item', 'play') : ''}</nav><div class="sidebar-bottom court-seal">${icon('shield')}<span>${UNIVERSES[language].era}</span></div></aside><main><header class="topbar"><a class="mobile-brand" href="#" data-action="home">${icon('mask')} ${UNIVERSES[language].title}</a><span class="breadcrumb">${screen==='home'?UNIVERSES[language].subtitle:UNIVERSES[language].title+' / '+screenLabel()}</span><div class="header-controls">${['home', 'rules'].includes(screen) ? button(tr('নিয়ম', 'Rules'), 'rules', 'header-rules', 'book') : ''}<button type="button" class="universe-toggle" data-action="universes" aria-label="${tr('জগৎ বেছে নাও','Choose universe')}" aria-haspopup="dialog">${icon('spark')}<span>${UNIVERSES[language].universeName}</span><span class="picker-chevron">⌄</span></button><button type="button" class="app-menu-toggle" data-action="app-menu" aria-label="${tr('মেনু','Menu')}" aria-haspopup="dialog">${menuIcon()}</button></div></header><div class="content ${screen === 'home' ? 'home-content' : screen === 'rules' ? 'rules-content' : 'game-content'}">${({ home, names, config, password, reveal, unlock, host, over, rules, 'last-chance': lastChance }[screen] || home)()}</div><footer class="app-credit">Developed by Tanim</footer></main>`; bind(); localize($('#app')); updateTimerDisplay(); }
function resume() { if (!game) return setup(); route(game.status === 'host' ? 'unlock' : game.status) }
function cancel() { confirm('গেম বাতিল করবে?', 'এই গেমের সব নাম, রোল ও অগ্রগতি মুছে যাবে।', () => { game = null; localStorage.removeItem(KEY); route('home') }, 'হ্যাঁ, বাতিল করো') }
function newGame() { if (game && game.status !== 'over') confirm('নতুন গেম শুরু করবে?', 'চলমান গেম মুছে যাবে।', setup, 'হ্যাঁ, নতুন গেম'); else setup() }
function end(w) { if (game.awardsApplied) return route('over'); game.timer = pauseTimer(game.timer); if (w === 'VILLAGER' && canGuessPolice(game)) { beginVillageFinale(game); save(); route('last-chance'); } else { finalizeVictory(game, w);recordLocalResult(game,language); save(); route('over'); } }
function suggest() { const w = suggestedWinner(game.players); if (w !== game.lastSuggestion) { game.lastSuggestion = w; save(); if (w) modal(winnerName(w) + tr(' জয়ের সুযোগ!', ' can win!'), w === 'VILLAGER' && canGuessPolice(game) ? tr('ঘাতকদের শেষ সেনাপতি-আন্দাজ বাকি। শেষ ধাপে যাবে?', 'The Mafia still get one final police guess. Go to the finale?') : tr('গেম শেষ করে জয়ের পয়েন্ট যোগ করবে?', 'Finish the game and add victory points?'), [{ label: tr('হ্যাঁ, শেষ ধাপে', 'Yes, finish up'), style: 'primary', action: () => end(w) }, { label: 'না, চলুক' }]); } }
const actions = { 'universes':openUniversePicker,'app-menu':openAppMenu,scores: openScores, 'timer-toggle': () => { game.timer = game.timer.running ? pauseTimer(game.timer) : startTimer(game.timer); save(); render() }, 'timer-reset': () => { game.timer = newTimer(game.timer.duration); save(); render() }, home: () => { if (screen === 'host') { game.status = 'unlock'; save() } route('home') }, rules: () => { if (['reveal', 'host', 'last-chance'].includes(screen)) return; route('rules') }, new: newGame, resume, fresh: setup, cancel, 'back-names': () => { game.status = 'names'; save(); route('names') }, 'back-config': () => { game.status = 'config'; save(); route('config') }, 'to-config': () => { if (game.names.length < 5) return; game.roleCounts ??= defaultRoleCounts(game.names.length); game.mafiaCount = game.roleCounts.MAFIA; game.status = 'config'; save(); route('config') }, 'to-password':()=>{if(setupError())return; game.status = 'password'; save(); route('password') }, minus: () => { game.mafiaCount = Math.max(1, game.mafiaCount - 1); save(); render() }, plus: () => { game.mafiaCount = Math.min(maxMafia(game.names.length), game.mafiaCount + 1); save(); render() }, reveal: () => { shown = true; render() }, 'next-player': () => { shown = false; game.revealIndex++; if (game.revealIndex === game.players.length) game.status = 'unlock'; save(); route(game.status) }, lock: () => { game.status = 'unlock'; save(); route('unlock') }, menu: () => { menu = !menu; render() }, round: () => confirm('রাউন্ড ' + bn(game.currentRound + 1) + ' শুরু করবে?', 'সবাই প্রস্তুত? এবার রাতের পালা।', () => { game.currentRound++; save(); render(); toast('রাউন্ড ' + bn(game.currentRound) + ' শুরু হয়েছে') }, 'হ্যাঁ, শুরু করো'), 'suggest-end': () => { const w = suggestedWinner(game.players); if (w) confirm(tr('গেম শেষ করবে?', 'Finish this game?'), w === 'VILLAGER' && canGuessPolice(game) ? tr('আগে ঘাতকদের শেষ সেনাপতি-আন্দাজ হবে।', 'The Mafia’s final police guess comes before the result.') : tr('বিজয়ীর পয়েন্ট নিজে যোগ হবে।', 'Victory points will be awarded automatically.'), () => end(w), tr('হ্যাঁ, শেষ ধাপে', 'Yes, finish up')) }, 'manual-end': () => modal(tr('কে জিতছে ক্ষমতার লড়াই?', 'Choose the winning side'), tr('প্রজারা জিতলে ঘাতকদের শেষ সেনাপতি-আন্দাজের সুযোগ থাকবে।', 'A village win first offers the Mafia one final police guess.'), [{ label: tr('ঘাতকদের জয়', 'Mafia win'), style: 'primary', action: () => confirm(tr('ঘাতকদের জয় ঘোষণা করবে?', 'Declare a Mafia win?'), tr('জয়ের পয়েন্ট অটো যোগ হবে।', 'Victory points will be added.'), () => end('MAFIA')) }, { label: tr('প্রজাদের জয়', 'Villagers win'), action: () => confirm(tr('প্রজাদের জয় চূড়ান্ত করবে?', 'Finalize a village win?'), tr('সেনাপতি থাকলে আগে ঘাতকদের শেষ আন্দাজ।', 'If Police are in play, the Mafia get their last guess first.'), () => end('VILLAGER')) }, { label: 'বাতিল' }]), rematch:()=>{const names=[...game.names],counts={...game.roleCounts};setup();game.names=names;game.roleCounts=counts;game.mafiaCount=counts.MAFIA;game.status='names';save();route('names')}};

function bind(){bindPinFields(document);bindTongControls();bindSeatingAndAssignment(); document.querySelectorAll('[data-action]').forEach(el => el.onclick = e => { if (el.getAttribute('type') === 'submit') return; e.preventDefault(); actions[el.dataset.action]?.() }); document.querySelectorAll('[data-eye]').forEach(el => el.onclick = () => { const input = document.getElementById(el.dataset.eye); input.type = input.type === 'password' ? 'text' : 'password'; el.setAttribute('aria-label', input.type === 'password' ? 'পাসওয়ার্ড দেখাও' : 'পাসওয়ার্ড লুকাও') });
    $('#name-form')?.addEventListener('submit', e => { e.preventDefault(); const input = $('#player-name'), error = input.value.trim().toLocaleLowerCase()===game.hostProfile?.name?.toLocaleLowerCase()?tr('হোস্ট খেলোয়াড় নন—অন্য নাম লেখো।','The host is not a player. Enter a different name.'):validateName(input.value, game.names); if (error) { $('#form-error').textContent = error; return } game.names.push(input.value.trim()); save(); render(); $('#player-name').focus() });
    document.querySelectorAll('[data-remove]').forEach(el => el.onclick = () => { const oldName=game.names[Number(el.dataset.remove)];delete game.manualRoles[oldName];if(game.startName===oldName)game.startName=null;game.names.splice(Number(el.dataset.remove),1); save(); render() });
    document.querySelectorAll('[data-edit]').forEach(el => el.onclick = () => { const i = Number(el.dataset.edit); $('#overlay').innerHTML = `<div class="scrim"><form class="dialog" id="edit-form"><h2>নাম বদলাও</h2><input class="edit-input" id="edit-name" value="${esc(game.names[i])}" aria-label="নতুন নাম" maxlength="40"><p class="error" id="edit-error"></p><button class="btn primary wide" type="submit">সেভ করো</button><button class="btn text wide" type="button" id="edit-cancel">বাতিল</button></form></div>`; $('#edit-name').focus(); $('#edit-cancel').onclick = () => $('#overlay').innerHTML = ''; $('#edit-form').onsubmit = e => { e.preventDefault(); const n = $('#edit-name').value, error = validateName(n, game.names, i); if (error) { $('#edit-error').textContent = error; return } const oldName=game.names[i];if(game.manualRoles[oldName]){game.manualRoles[n.trim()]=game.manualRoles[oldName];if(n.trim()!==oldName)delete game.manualRoles[oldName];}if(game.startName===oldName)game.startName=n.trim();game.names[i]=n.trim(); save(); $('#overlay').innerHTML = ''; render() } });
    $('#password-form')?.addEventListener('submit', async e => { e.preventDefault(); if(busy)return;if(setupError()){$('#form-error').textContent=roleConfigError(setupError());return;}const pw=$('#password').value; if (!validPin(pw)) { $('#form-error').textContent = tr('ঠিক চারটি সংখ্যা দাও।','Enter exactly four digits.'); return } if (pw !== $('#repeat').value) { $('#form-error').textContent = 'পাসওয়ার্ড মিলছে না'; return } busy = true; const btn = e.target.querySelector('[type="submit"]'); btn.disabled = true; try { const salt = Array.from(crypto.getRandomValues(new Uint8Array(16))); const hash = await passwordHash(pw, salt); game.salt = salt; game.passwordHash = hash;game.pinFormat='numeric-4'; game.players=game.assignmentMode==='MANUAL'?assignManualRoles(game.names,game.roleCounts,game.manualRoles):assignRoles(game.names,game.roleCounts);game.revealOrder=sequentialOrder(game.names);assignCharacterIndexes(game.players,game.revealOrder); game.status = 'reveal'; save(); route('reveal') } catch { $('#form-error').textContent = 'নিরাপদ ব্রাউজারে (HTTPS বা localhost) অ্যাপ খোলো।' } finally { busy = false; btn.disabled = false } });
    $('#unlock-form')?.addEventListener('submit', async e => { e.preventDefault(); if (busy) return; busy = true; const input = $('#unlock'), btn = e.target.querySelector('[type="submit"]'); btn.disabled = true; try { const hash = await passwordHash(input.value, game.salt); if (hash === game.passwordHash) { if(validPin(input.value))game.pinFormat='numeric-4';game.status = 'host'; save(); route('host') } else { input.value = ''; $('#form-error').textContent = 'ভুল পাসওয়ার্ড'; e.target.classList.add('shake'); await new Promise(r => setTimeout(r, 1000)); e.target.classList.remove('shake') } } catch { $('#form-error').textContent = 'আনলক করা যাচ্ছে না। আবার চেষ্টা করো।' } finally { busy = false; btn.disabled = false } });
    document.querySelectorAll('[data-player]').forEach(el => el.onclick = () => { const p = game.players[Number(el.dataset.player)]; if (p.quit) return toast(tr('খেলা ছেড়েছেন। পরের খেলায় অংশ নিতে পারবেন।','This player quit and can return next game.')); if (p.isAlive) openElimination(p); else confirm(tr('ফিরিয়ে আনবে: ', 'Restore: ') + p.name, tr('ভুল করে বাদ পড়লে আবার খেলায় ফেরাও।', 'Bring this player back to correct a mistake.'), () => { p.isAlive = true; p.diedInRound = null; p.deathCause = null; save(); render(); suggest(); }, tr('হ্যাঁ, ফিরিয়ে আনো', 'Yes, restore')); });
}

function hidePrivate() { if (screen === 'reveal' && shown) { shown = false; render() } if (screen === 'host') { game.status = 'unlock'; save(); route('unlock') } $('#overlay').innerHTML = '' }
document.addEventListener('visibilitychange', () => { if (document.hidden) hidePrivate() }); window.addEventListener('blur', hidePrivate);
window.onNativePause = hidePrivate;
window.onNativeBack = () => { if ($('.score-sheet')) { $('#overlay').innerHTML = ''; return; } if (['reveal', 'unlock', 'password', 'last-chance'].includes(screen)) return; if (screen === 'host') confirm('গেম থেকে বের হবে?', 'গেম সেভ থাকবে। আবার খুলতে পাসওয়ার্ড লাগবে।', () => { game.status = 'unlock'; save(); route('home') }, 'বের হও'); else if (screen === 'config') actions['back-names'](); else route('home') };
history.replaceState({}, '', location.pathname); history.pushState({}, '', location.pathname); window.addEventListener('popstate', () => { window.onNativeBack(); history.pushState({}, '', location.pathname) });
if ('serviceWorker' in navigator && !window.Android && location.protocol !== 'file:') navigator.serviceWorker.register('./sw.js').catch(() => { });
const translator=new MutationObserver(()=>{translator.disconnect();['#app','#overlay','#toast'].forEach(id=>localize($(id)));observeTranslations();});
function observeTranslations() { ['#app', '#overlay', '#toast'].forEach(id => translator.observe($(id), { childList: true, subtree: true, characterData: true })); }
observeTranslations();
setInterval(tickTimer, 250);
render();

function sunIcon() { return '<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/></svg>' }
function roleAvatar(role,cls='',index=0){return `<img class="character-avatar ${cls}" src="${characterImage(role,language,index)}" alt="${roleName(role)}" width="80" height="80">`}
function rerenderPreferences() { const values = Array.from(document.querySelectorAll('#app input')).map(el => [el.id, el.value]); render(); values.forEach(([id, value]) => { const el = document.getElementById(id); if (el) el.value = value; }); }
function timerLabel() { const left = secondsLeft(game.timer); return `${bn(Math.floor(left / 60)).padStart(2, language !== 'bn' ? '0' : '০')}:${bn(left % 60).padStart(2, language !== 'bn' ? '0' : '০')}`; }
function hostTools() { return `<section class="host-tools"><div class="tool-heading"><div><span class="eyebrow">${tr('সবাইকে বলতে দাও', 'LET EVERYONE HAVE THEIR SAY')}</span><h2>${tr('আলোচনার সময়', 'Discussion time')}</h2></div>${button(tr('স্কোর ও র‍্যাঙ্কিং', 'Scores & rankings'), 'scores', 'secondary', 'trophy')}</div><div class="discussion-timer ${secondsLeft(game.timer) === 0 ? 'expired' : ''}"><div><div class="timer-digits" id="timer-clock" role="timer" aria-label="${tr('বাকি সময়', 'Time remaining')}">${timerLabel()}</div><div class="timer-state" id="timer-state" role="status" aria-live="polite">${timerStatus()}</div></div><div class="timer-actions">${button(game.timer.running ? tr('বিরতি', 'Pause') : tr('শুরু', 'Start'), 'timer-toggle', 'primary', game.timer.running ? '' : 'play')}${button(tr('রিসেট', 'Reset'), 'timer-reset', 'secondary', '')}</div></div><label class="timer-duration">${tr('সময় নির্ধারণ (মিনিট)', 'Duration (minutes)')}<input id="timer-duration" type="number" min="1" max="30" step="1" value="${game.timer.duration / 60}" ${game.timer.running ? 'disabled' : ''} aria-label="${tr('আলোচনার সময় মিনিটে', 'Discussion duration in minutes')}"><small>${tr('১–৩০ মিনিট · বিরতিতে বদলাও', '1–30 minutes · edit while paused')}</small></label></section>` }
function timerStatus() { return game.timer.running ? tr('আলোচনা চলছে…', 'Discussion in progress…') : secondsLeft(game.timer) === 0 ? tr('সময় শেষ! সিদ্ধান্ত নেওয়ার পালা।', 'Time’s up! Time for a decision.') : secondsLeft(game.timer) === game.timer.duration ? tr('সবাই প্রস্তুত হলে শুরু করো', 'Start when everyone is ready') : tr('একটু বিরতি। আবার শুরু করতে পারো।', 'Paused. Pick up where you left off.'); }
function updateTimerDisplay() { if (!game?.timer) return; if(game.timer.running&&secondsLeft(game.timer)===0&&expiredSound!==game.timer.endsAt){expiredSound=game.timer.endsAt;sound('timer');} const clock = $('#timer-clock'); if (clock) { clock.textContent = timerLabel(); $('#timer-state').textContent = timerStatus(); clock.closest('.discussion-timer').classList.toggle('expired', secondsLeft(game.timer) === 0); } const duration = $('#timer-duration'); if (duration) { duration.oninput = e => { const minutes = Number(e.target.value); if (!Number.isInteger(minutes) || minutes < 1 || minutes > 30) return; game.timer = newTimer(minutes * 60); save(); $('#timer-clock').textContent = timerLabel(); $('#timer-state').textContent = timerStatus(); }; duration.onblur = e => { const minutes = Number(e.target.value); if (!Number.isInteger(minutes) || minutes < 1 || minutes > 30) { e.target.value = game.timer.duration / 60; toast(tr('১ থেকে ৩০ মিনিট বেছে নাও', 'Choose 1 to 30 minutes')); } }; } }

function tickTimer() { if (!game?.timer?.running) return; if (secondsLeft(game.timer) === 0) { game.timer = pauseTimer(game.timer); save(); if (screen === 'host') { render(); toast(tr('আলোচনার সময় শেষ!', 'Discussion time is up!')); } } else if (screen === 'host') { const clock = $('#timer-clock'); if (clock && clock.textContent !== timerLabel()) clock.textContent = timerLabel(); } }
function openScores() {
    if (!game || !['host', 'over'].includes(screen)) return; const ranked = rankedPlayers(game.players); $('#overlay').innerHTML = `<div class="scrim score-scrim"><section class="score-sheet" role="dialog" aria-modal="true" aria-labelledby="score-title"><div class="sheet-handle"></div><div class="sheet-header"><div><span class="eyebrow">${tr('হোস্টের স্কোরশিট · যেকোনো রাউন্ডে', 'HOST SCORESHEET · EVERY ROUND')}</span><h2 id="score-title">${tr('কে সবার চেয়ে চালাক?', 'Who’s playing it smartest?')}</h2></div><button type="button" class="icon-btn" id="close-scores" aria-label="${tr('স্কোরশিট বন্ধ করো', 'Close scoresheet')}">${icon('close')}</button></div><p class="sheet-description">${screen === 'over' ? tr('এখানে ম্যানুয়াল ও অটো জয়ের পয়েন্ট মিলিয়ে মোট স্কোর। জয়ের পয়েন্ট একবারই যোগ হয়েছে।', 'Totals include host points plus automatic victory points. Victory points were awarded once.') : tr('যুক্তি, পরিকল্পনা ও অভিনয়ের জন্য পয়েন্ট দাও। জয়ের পয়েন্ট শেষে যোগ হবে।', 'Award points for bluffs, reasoning and plans. Victory points are added automatically at the end.')}</p><div class="score-legend"><span>${tr('প্লেয়ার ও পরিকল্পনার নোট', 'PLAYER & PLAN NOTES')}</span><span>${tr('পয়েন্ট', 'POINTS')}</span></div><div class="score-rows">${ranked.map(p => `<article class="score-row" data-score-id="${esc(p.id)}"><div class="score-top"><span class="rank ${p.rank === 1 ? 'first' : ''}">${p.rank === 1 ? icon('trophy') : bn(p.rank)}</span>${roleAvatar(p.role, 'score-portrait')}<div class="score-identity"><strong data-player-name>${esc(p.name)}</strong><small>${roleName(p.role)} · ${p.isAlive ? tr('জীবিত', 'Alive') : tr('মৃত', 'Eliminated')}${screen === 'over' ? ' · +' + bn(p.winPoints || 0) + ' ' + tr('জয়ের', 'win') : ''}</small></div><div class="score-controls"><button type="button" ${screen === 'over' ? 'disabled' : ''} data-score-delta="-1" aria-label="${tr('পয়েন্ট কমাও: ', 'Decrease points: ') + esc(p.name)}">−</button><input type="number" class="score-value" ${screen === 'over' ? 'disabled' : ''} value="${scoreOf(p)}" min="-9999" max="9999" step="1" aria-label="${tr('পয়েন্ট: ', 'Points: ') + esc(p.name)}"><button type="button" ${screen === 'over' ? 'disabled' : ''} data-score-delta="1" aria-label="${tr('পয়েন্ট বাড়াও: ', 'Increase points: ') + esc(p.name)}">+</button></div></div><label class="plan-label">${tr('পরিকল্পনা / খেলার নোট', 'Plan / play notes')}<textarea class="plan-note" maxlength="500" rows="2" placeholder="${tr('যেমন: দুর্দান্ত ব্লাফ, মাফিয়াকে ধরেছে…', 'e.g. Brilliant bluff, spotted the Mafia…')}" aria-label="${tr('পরিকল্পনার নোট: ', 'Plan notes: ') + esc(p.name)}">${esc(p.plan || '')}</textarea></label></article>`).join('')}</div><div class="sheet-footer">${icon('check')} ${tr('পয়েন্ট ও নোট নিজে থেকেই সেভ হচ্ছে', 'Points and notes save automatically')}<button class="btn primary" type="button" id="done-scores">${tr('হয়ে গেছে', 'Done')}</button></div></section></div>`;
    const close = () => { $('#overlay').innerHTML = ''; $('[data-action="scores"]')?.focus(); }; $('#close-scores').onclick = close; $('#done-scores').onclick = close;
    document.querySelectorAll('.score-row').forEach(row => { const p = game.players.find(p => p.id === row.dataset.scoreId); row.querySelectorAll('[data-score-delta]').forEach(btn => btn.onclick = () => { try { updateScore(p, scoreOf(p) + Number(btn.dataset.scoreDelta)); save(); openScores(); } catch { toast(tr('পয়েন্ট -৯৯৯৯ থেকে ৯৯৯৯ হতে হবে', 'Points must be between -9999 and 9999')); } }); const scoreInput = row.querySelector('.score-value'); scoreInput.oninput = e => { const v = e.target.value; try { if (v.trim() === '') return; updateScore(p, Number(v)); save(); refreshRanks(); } catch { } }; scoreInput.onblur = e => { const v = e.target.value; if (!v.trim() || !Number.isSafeInteger(Number(v)) || Math.abs(Number(v)) > 9999) { e.target.value = scoreOf(p); toast(tr('পূর্ণ সংখ্যায় পয়েন্ট দাও (-৯৯৯৯ থেকে ৯৯৯৯)', 'Enter whole-number points (-9999 to 9999)')); } }; row.querySelector('.plan-note').oninput = e => { p.plan = e.target.value.slice(0, 500); save(); }; });
    // Keep keyboard focus in the sheet; close with Escape without affecting the timer.
    const sheet = $('.score-sheet'); sheet.onkeydown = e => { if (e.key === 'Escape') { e.preventDefault(); close(); } if (e.key === 'Tab') { const controls = [...sheet.querySelectorAll('button,input,textarea')], first = controls[0], last = controls.at(-1); if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); } else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); } } }; $('#close-scores').focus();
}

function refreshRanks() { const active = document.activeElement, container = $('.score-rows'); rankedPlayers(game.players).forEach(p => { const row = document.querySelector(`[data-score-id="${p.id}"]`); if (row) { const rank = row.querySelector('.rank'); rank.classList.toggle('first', p.rank === 1); rank.innerHTML = p.rank === 1 ? icon('trophy') : bn(p.rank); rank.setAttribute('aria-label', tr('র‍্যাঙ্ক ', 'Rank ') + bn(p.rank)); container.append(row); } }); if (active?.isConnected) { active.focus({ preventScroll: true }); active.scrollIntoView({ block: 'nearest' }); } }

function roleName(role){return role==='HOST'?tr('হোস্ট','Host'):UNIVERSES[language].roles[role].name;}
function teamName(team){return team==='MAFIA'?tr('ঘাতক দল','Mafia team'):tr('প্রজাদের দল','Village team');}
function winnerName(w){return w==='MAFIA'?tr('ঘাতকদের','Mafia'):tr('প্রজাদের','Villagers');}
function teaIcon() { return '<svg class="icon tea-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 9h13v8a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4V9ZM17 10h2a3 3 0 0 1 0 6h-2M7 2c-3 3 3 3 0 6m6-6c-3 3 3 3 0 6M2 22h18"/></svg>'; }
function roleTagline(role){return UNIVERSES[language].roles[role].tag;}
function roleConfigError(error){return ({HOST_IN_PLAYERS:tr('হোস্টের নাম খেলোয়াড়ের তালিকা থেকে সরাও।','Remove the host from the player list.'),PLAYER_COUNT:tr('৫ থেকে ২০ জন লাগবে।','You need 5–20 players.'),ROLE_COUNT:tr('রোলের সংখ্যা পূর্ণ সংখ্যা হতে হবে।','Role counts must be whole numbers.'),NO_MAFIA:tr('কমপক্ষে একজন ঘাতক লাগবে।','At least one Mafia is required.'),TOO_MANY_ROLES:tr('প্লেয়ারের চেয়ে রোল বেশি। কিছু রোল কমাও।','More roles than players. Reduce some counts.'),MAFIA_MAJORITY:tr('ঘাতক ও বিশ্বাসঘাতক মিলিয়ে অন্যদের চেয়ে কম হতে হবে।','Mafia and Betrayers together must be fewer than everyone else.'),MISSING_ASSIGNMENTS:tr('প্রতিটি প্লেয়ারের রোল বেছে দাও।','Assign a role to every player.'),ASSIGNMENT_COUNTS:tr('বেছে দেওয়া রোলের সংখ্যা ওপরের হিসাবের সাথে মিলতে হবে।','Assignments must match the role counts above.')})[error]||'';}
function scoringLegend(){return `<div class="scoring-legend"><span>${icon('trophy')} ${tr('জয়ের পয়েন্ট','VICTORY POINTS')}</span><div><b class="red">${tr('ঘাতক +৩','Mafia +3')}</b><b>${tr('বিশ্বাসঘাতক +২','Betrayer +2')}</b><b>${tr('হোস্ট +১','Host +1')}</b><b class="green">${tr('রাজবৈদ্য / সেনাপতি +২','Doctor / Police +2')}</b><b class="gold">${tr('অন্য প্রজা +১','Other villagers +1')}</b></div><small>${tr('শুধু বিজয়ী দলের সবাই · জীবিত বা মৃত','All winning-team players · alive or eliminated')}</small></div>`;}
function bindTongControls() {
    document.querySelectorAll('[data-role-count]').forEach(el => el.onclick = () => { const key = el.dataset.roleCount; game.roleCounts[key] = Math.max(key === 'MAFIA' ? 1 : 0, Math.min(game.names.length, game.roleCounts[key] + Number(el.dataset.delta))); game.mafiaCount = game.roleCounts.MAFIA; save(); render(); });
    document.querySelectorAll('[name="police-guess"]').forEach(el => el.onchange = () => { game.guessTarget = el.value; save(); $('#submit-guess').disabled = false; });
    $('#submit-guess')?.addEventListener('click', () => { const target = game.players.find(p => p.id === game.guessTarget); if (!target) return; confirm(tr('এটাই শেষ আন্দাজ?', 'Lock in the final guess?'), tr('সেনাপতি হিসেবে আন্দাজ: ', 'Guessing Police: ') + target.name + tr('। একবারই সুযোগ!', ' — one chance only!'), () => { resolveFinalGuess(game, target.id);recordLocalResult(game,language); save(); route('over'); }, tr('হ্যাঁ, নাম লক করো', 'Yes, lock the guess')); });
    $('#skip-guess')?.addEventListener('click', () => confirm(tr('শেষ আন্দাজ বাদ দেবে?', 'Skip the final guess?'), tr('প্রজাদের জয় চূড়ান্ত হবে, পয়েন্ট যোগ হবে।', 'The village win will stand and points will be awarded.'), () => { resolveFinalGuess(game, null);recordLocalResult(game,language); save(); route('over'); }, tr('হ্যাঁ, গ্রাম জিতুক', 'Yes, village wins')));
}
function openElimination(player) {
    $('#overlay').innerHTML = `<div class="scrim"><form class="dialog elimination-dialog" id="elimination-form" role="dialog" aria-modal="true" aria-label="${tr('প্লেয়ার বাদ দাও', 'Eliminate player')}"><div class="dialog-mark">${icon('moon')}</div><h2><span data-player-name>${esc(player.name)}</span>${tr(' কীভাবে বাদ?', ' is out how?')}</h2><p>${roleName(player.role)} · ${tr('রাউন্ড ', 'Round ') + bn(game.currentRound)}</p><label class="cause-option ${player.role === 'ASTROLOGER' ? 'unavailable' : ''}"><input type="radio" name="death-cause" value="NIGHT" ${player.role === 'ASTROLOGER' ? 'disabled' : ''}>${icon('moon')}<span><strong>${tr('ঘাতকের রাতের আক্রমণ', 'Mafia night attack')}</strong><small>${player.role === 'ASTROLOGER' ? tr('গণক রাতে অক্ষত থাকবে', 'The Consigliere cannot be killed at night') : tr('রক্ষা না পেলে মৃত ঘোষণা করো', 'Eliminate only if not protected')}</small></span></label><label class="cause-option"><input type="radio" name="death-cause" value="VOTE" ${player.role === 'ASTROLOGER' ? 'checked' : ''}>${icon('people')}<span><strong>${tr('সবার ভোটে বাদ', 'Voted out')}</strong><small>${tr('দিনের আলোচনার পর ভোটের ফল', 'The result of the daytime vote')}</small></span></label><label class="cause-option"><input type="radio" name="death-cause" value="QUIT"><span><strong>${tr('খেলা ছেড়ে যাচ্ছেন','Quit game')}</strong><small>${tr('এই খেলায় আর অংশ নেবেন না','No further participation this game')}</small></span></label><p class="error" id="elimination-error" role="alert"></p><button class="btn primary wide" type="submit">${tr('হ্যাঁ, বাদ দাও', 'Yes, eliminate')}</button><button class="btn text wide" type="button" id="cancel-elimination">${tr('বাতিল', 'Cancel')}</button></form></div>`;
    $('#cancel-elimination').onclick = () => $('#overlay').innerHTML = ''; $('#elimination-form').onsubmit = e => { e.preventDefault(); const cause = $('[name="death-cause"]:checked')?.value; if (!cause) { $('#elimination-error').textContent = tr('রাতের আক্রমণ নাকি ভোট, বেছে নাও।', 'Choose a night attack or vote-out.'); return; } try { if(cause==='QUIT'){player.quit=true;player.isAlive=false;player.deathCause='QUIT';sound('out');}else eliminatePlayer(game, player.id, cause); save(); $('#overlay').innerHTML = ''; render(); suggest(); } catch { $('#elimination-error').textContent = tr('ঘাতক রাতে গণককে মারতে পারে না।', 'Mafia cannot kill Jotishi at night.'); } };
    $('#cancel-elimination').focus();
}
function lastChance() { return `<section class="last-chance"><span class="pill">${icon('lock')} ${tr('এখানে কারও রোল দেখানো হচ্ছে না', 'NO ROLES SHOWN ON THIS SCREEN')}</span><div class="final-guess-icon">${icon('mask')}<span>?</span></div>${heading(tr('শেষ সুযোগ', 'THE LAST CHANCE'), tr('সেনাপতি কে?','Who’s the Police?'), tr('প্রজাদের জয় আসন্ন। ঘাতক দল একসঙ্গে একটি নাম বলবে। সেনাপতিকে চিহ্নিত করতে পারলে জয় ঘাতকদের।', 'The village is about to win. The Mafia get one shared guess: name a Police player to overturn the result.'))}<div class="guess-note">${tr('জীবিত বা মৃত যেকোনো সেনাপতিকে ধরলেই হবে। নাম লক করার আগে কারও রোল দেখাবে না।', 'Every name is shown. Any Police player counts, alive or eliminated. Keep all roles secret until the guess is locked.')}</div><fieldset class="guess-players"><legend>${tr('ঘাতকদের শেষ আন্দাজ', 'The Mafia’s one and only guess')}</legend>${game.players.map(p => `<label class="guess-option"><input type="radio" name="police-guess" value="${esc(p.id)}" ${game.guessTarget === p.id ? 'checked' : ''}><span class="generic-person">${icon('person')}</span><strong data-player-name>${esc(p.name)}</strong></label>`).join('')}</fieldset><button class="btn primary wide" id="submit-guess" type="button" ${game.guessTarget ? '' : 'disabled'}>${tr('এই নাম লক করো', 'Lock this guess')}${icon('lock')}</button><button class="btn text wide" id="skip-guess" type="button">${tr('আন্দাজ বাদ — প্রজাদের জয়', 'Skip guess — village wins')}</button></section>`; }

function setupError(){if(game.hostProfile?.name&&game.names.some(name=>name.toLocaleLowerCase()===game.hostProfile.name.toLocaleLowerCase()))return 'HOST_IN_PLAYERS';return validateRoleCounts(game.names.length,game.roleCounts)||(game.assignmentMode==='MANUAL'?validateManualAssignments(game.names,game.roleCounts,game.manualRoles):null);}
function assignmentToggle(){return `<div class="assignment-switch" role="group" aria-label="${tr('রোল বণ্টনের পদ্ধতি','Role assignment mode')}"><button type="button" data-assignment-mode="AUTO" aria-pressed="${game.assignmentMode!=='MANUAL'}">${icon('spark')} ${tr('স্বয়ংক্রিয়','Random roles')}</button><button type="button" data-assignment-mode="MANUAL" aria-pressed="${game.assignmentMode==='MANUAL'}">${icon('person')} ${tr('হোস্ট বেছে দেবেন','Host assigns')}</button></div><p class="assignment-hint">${game.assignmentMode==='MANUAL'?tr('নিচে প্রতিটি নামের পাশে রোল বেছে দাও। সংখ্যাগুলো মিললেই পরের ধাপে যাবে।','Choose a role beside each name below. Assignments must match the counts.'):tr('নির্ধারিত সংখ্যার রোলগুলো এলোমেলোভাবে বণ্টন হবে।','Roles will be shuffled using your chosen counts.')}</p>`;}
function manualAssignmentPanel(counts){return `<section class="manual-panel"><div class="section-title"><h2>${tr('কে কোন রোল পাবে?','Who gets which role?')}</h2></div>${game.names.map((name,i)=>`<label class="manual-row"><span><small>${tr('আসন ','Seat ')+bn(i+1)}</small><strong data-player-name>${esc(name)}</strong></span><select data-manual-name="${esc(name)}" aria-label="${tr('রোল: ','Role: ')+esc(name)}"><option value="">${tr('রোল বেছে নাও','Choose role')}</option>${Object.entries(counts).filter(([,count])=>count>0).map(([role,count])=>{const used=game.names.filter(n=>n!==name&&game.manualRoles[n]===role).length;return `<option value="${role}" ${game.manualRoles[name]===role?'selected':''} ${used>=count&&game.manualRoles[name]!==role?'disabled':''}>${roleName(role)} (${bn(Math.max(0,count-used))})</option>`}).join('')}</select></label>`).join('')}<p>${tr('বন্ধনীর সংখ্যা ওই প্লেয়ারের জন্য উপলব্ধ রোলের সংখ্যা।','The number in brackets shows available places for that role.')}</p></section>`;}
function seatingPreview(){const order=sequentialOrder(game.names);return `<section class="seating-preview"><span>${icon('arrow')} ${tr('তালিকা ধরে ফোন চালাও','PASS IN LIST ORDER')}</span><strong>${tr('ক্রম: ১ → ২ → ৩ → ৪','SEQUENCE: 1 → 2 → 3 → 4')}</strong><p>${order.map(i=>`<span data-player-name>${esc(game.names[i])}</span>`).join(' <b>→</b> ')}</p></section>`;}
function bindSeatingAndAssignment(){
 document.querySelectorAll('[data-assignment-mode]').forEach(el=>el.onclick=()=>{game.assignmentMode=el.dataset.assignmentMode;save();render();});
 document.querySelectorAll('[data-manual-name]').forEach(el=>el.onchange=()=>{game.manualRoles[el.dataset.manualName]=el.value;save();render();});
 const list=$('.sortable-seats');if(list&&game.names.length)disposeSeatSort=mountSeatSort(list,{onCommit:(names,name)=>{game.names=moveSeat(game.names,game.names.indexOf(name),names.indexOf(name));save();render();const live=$('#seat-announcement');if(live)live.textContent=language==='bn'?`${name}: নতুন আসন ${bn(names.indexOf(name)+1)}, নামের ক্রম রইল সঠিক।`:`${name} dropped in seat ${bn(names.indexOf(name)+1)}.`;document.querySelectorAll('[data-drag-handle]').forEach(handle=>{if(handle.closest('[data-sort-name]').dataset.sortName===name)handle.focus({preventScroll:true});});},announce:text=>{const live=$('#seat-announcement');if(live)live.textContent=text;},labels:(key,name,index)=>{if(key==='number')return bn(index);const seat=bn(index);return language==='bn'?({lift:`${name}: ধরেছ যাকে, তিরে সরাও তাকে।`,move:`${name}: আসন ${seat} হলো, চাইলে আরও চলো।`,drop:`${name}: আসন ${seat}-এ রাখা, ঠিক রইল নামের খাতা।`,cancel:`${name}: আগের আসন রইল ধরে, ফেরত এলে নিজের ঘরে।`})[key]:({lift:`${name} lifted. Use arrow keys to move.`,move:`${name}, seat ${seat}.`,drop:`${name} dropped in seat ${seat}.`,cancel:`Reordering cancelled for ${name}.`})[key];}});
}

function screenLabel(){return ({names:tr('আসন','Seats'),config:tr('রোল বণ্টন','Role assignment'),password:tr('হোস্ট লক','Host lock'),unlock:tr('হোস্ট লক','Host lock'),reveal:tr('গোপন পরিচয়','Secret identity'),host:tr('হোস্টের পাতা','Host panel'),over:tr('ফলাফল','Results'),rules:tr('খেলার নিয়ম','Rules'),'last-chance':tr('শেষ আন্দাজ','Last guess')})[screen]||'';}

function gripIcon(){return '<svg class="icon" viewBox="0 0 20 24" fill="currentColor" aria-hidden="true"><circle cx="6" cy="5" r="1.6"/><circle cx="13" cy="5" r="1.6"/><circle cx="6" cy="12" r="1.6"/><circle cx="13" cy="12" r="1.6"/><circle cx="6" cy="19" r="1.6"/><circle cx="13" cy="19" r="1.6"/></svg>';}
function menuIcon(){return '<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" aria-hidden="true"><path d="M4 6h16M4 12h16M4 18h16"/></svg>';}
function openUniversePicker(){if(game&&!['over','names','config','password'].includes(game.status)&&screen!=='host'){toast(tr('জগৎ বদলাতে হোস্টের তালা খোলো।','Unlock the host panel to change the universe.'));return;}
 $('#overlay').innerHTML=`<div class="scrim"><section class="dialog universe-dialog" role="dialog" aria-modal="true" aria-labelledby="universe-title"><div class="picker-title"><div><span class="eyebrow">${tr('জগৎ বদলাও, রূপটি পাল্টাও','CHOOSE YOUR WORLD')}</span><h2 id="universe-title">${tr('কোন জগতে যাবে?','Choose a universe')}</h2></div><button type="button" class="icon-btn" id="close-universe" aria-label="${tr('বন্ধ করো','Close')}">${icon('close')}</button></div><div class="universe-options">${WORLD_OPTIONS.map(world=>`<button type="button" class="universe-option" data-world="${world.id}" aria-pressed="${world.id===universeId}"><img src="assets/${world.locale}/cover.png" alt="" width="160" height="90"><span><strong>${world.name[language==='bn'?'bn':'en']}</strong><small>${world.id==='classic'?tr('পাড়ার চায়ে আড্ডা জমে, পাঁচ পরিচয় গোপন নামে','A Bangladeshi neighborhood. Five familiar roles.'):world.id==='polashi'?tr('পলাশীর টান, চক্রান্তের গান','A royal court of power and deception'):tr('সিসিলির দল, গোপন ছল','A Sicilian village of loyalty and betrayal')}</small></span><span class="world-check">${world.id===universeId?icon('check'):icon('arrow')}</span></button>`).join('')}</div></section></div>`;
 $('#close-universe').onclick=()=>{$('#overlay').innerHTML='';$('[data-action="universes"]')?.focus();};document.querySelectorAll('[data-world]').forEach(el=>el.onclick=()=>{if(el.dataset.world==='classic'&&game?.players?.some(p=>['ASTROLOGER','BODYGUARD'].includes(p.role))&&!['names','config','password'].includes(game.status)){toast('Finish this game before choosing Classic.');return;}setUniverse(el.dataset.world);if(language==='classic'&&game?.roleCounts){game.roleCounts.ASTROLOGER=0;game.roleCounts.BODYGUARD=0;game.manualRoles=Object.create(null);save();}$('#overlay').innerHTML='';rerenderPreferences();$('[data-action="universes"]')?.focus();});bindOverlayKeys($('.universe-dialog'),()=>$('#close-universe').click());$('#close-universe').focus();
}
function openAppMenu(){
 const items=[{label:tr('সব খেলা','All games'),icon:'home',action:()=>location.href='index.html'},{label:tr('শব্দ','Sound')+': '+(soundEnabled()?tr('চালু','On'):tr('বন্ধ','Off')),icon:'play',action:()=>{toggleSound();openAppMenu();}},{label:tr('আমার নাম ও ছবি','My name & photo'),icon:'person',action:openLocalProfile},{label:tr('নিজের ফোনে একসঙ্গে খেলো','Play on separate phones'),icon:'people',action:()=>{location.href='room.html?lang='+language;}}];
 if(screen==='host')items.push({label:tr('হোস্টের পাতা লক করো','Lock host panel'),icon:'lock',action:()=>actions.lock()});
 if(!['reveal','unlock','last-chance','host'].includes(screen))items.push({label:tr('খেলার নিয়ম','Game rules'),icon:'book',action:()=>actions.rules()});
 if(!['reveal','unlock','last-chance'].includes(screen)&&screen!=='home')items.push({label:tr('হোমে চলো','Go home'),icon:'home',action:()=>actions.home()});
 $('#overlay').innerHTML=`<div class="scrim"><section class="dialog app-menu-dialog" role="dialog" aria-modal="true" aria-labelledby="app-menu-title"><div class="picker-title"><h2 id="app-menu-title">${tr('মেনু','Menu')}</h2><button type="button" id="close-app-menu" class="icon-btn" aria-label="${tr('বন্ধ করো','Close')}">${icon('close')}</button></div><div class="app-menu-items">${items.map((item,i)=>`<button class="btn secondary wide" type="button" data-menu-item="${i}">${icon(item.icon)}${esc(item.label)}${icon('arrow')}</button>`).join('')}</div></section></div>`;
 $('#close-app-menu').onclick=()=>{$('#overlay').innerHTML='';$('[data-action="app-menu"]')?.focus();};document.querySelectorAll('[data-menu-item]').forEach(el=>el.onclick=()=>{$('#overlay').innerHTML='';items[Number(el.dataset.menuItem)].action();});bindOverlayKeys($('.app-menu-dialog'),()=>$('#close-app-menu').click());$('#close-app-menu').focus();
}
function bindOverlayKeys(dialog,close){dialog.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();close();}if(e.key==='Tab'){const controls=[...dialog.querySelectorAll('button:not([disabled]),a,input,select')],first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};}

function openLocalProfile(){
 let profile=saveProfile(readProfile()),photo=profile.photo;
 $('#overlay').innerHTML=`<div class="scrim"><section class="dialog" role="dialog" aria-modal="true" aria-label="${tr('আমার নাম ও ছবি','My name & photo')}"><div class="picker-title"><h2>${tr('আমার নাম ও ছবি','My name & photo')}</h2><button type="button" id="close-profile" class="icon-btn" aria-label="${tr('বন্ধ করো','Close')}">${icon('close')}</button></div><form id="local-profile-form"><div class="profile-picture-preview">${photo?`<img src="${photo}" alt="">`:`<span>${esc(profile.name.charAt(0)||'♜')}</span>`}</div><label for="local-profile-name">${tr('তোমার নাম','Your name')}</label><input id="local-profile-name" value="${esc(profile.name)}" maxlength="20" required><label for="local-profile-photo">${tr('নিজের ছবি · ইচ্ছেমতো','Your photo · optional')}</label><input id="local-profile-photo" type="file" accept="image/png,image/jpeg,image/webp"><p>${tr('হোস্ট হিসেবে সম্পূর্ণ আসরে এক পয়েন্ট।','The host earns 1 point per completed game.')} ${bn(profile.score)}</p><p class="error" id="profile-error"></p><button class="btn primary wide" type="submit">${tr('পরিচয় রেখে দাও','Save profile')}</button></form></section></div>`;
 const close=()=>$('#overlay').innerHTML='';$('#close-profile').onclick=close;
 $('#local-profile-photo').onchange=async e=>{try{photo=await photoFromFile(e.target.files[0]);$('.profile-picture-preview').innerHTML=`<img src="${photo}" alt="">`;}catch{$('#profile-error').textContent=tr('পাঁচ মেগাবাইটের মধ্যে ছবি দাও।','Choose a JPEG, PNG, or WebP under 5 MB.');}};
 $('#local-profile-form').onsubmit=e=>{e.preventDefault();const name=$('#local-profile-name').value.trim();if(!name)return;if(game?.names.some(n=>n.toLocaleLowerCase()===name.toLocaleLowerCase())){$('#profile-error').textContent=tr('হোস্টের নাম খেলোয়াড়ের তালিকায় আছে। আগে তালিকা থেকে সরাও।','The host’s name is in the player list. Remove it before saving this host profile.');return;}profile=saveProfile({...profile,name,photo});if(game&&['names','config','password'].includes(game.status)){game.hostProfile=profile;save();}close();render();};
 bindOverlayKeys($('.dialog'),close);$('#local-profile-name').focus();
}

function extraCastCards(){return (language==='classic'?[['HOST',0]]:[['HOST',0],['MAFIA',1],['MAFIA',2]]).map(([role,index])=>{const c=characterFor(role,language,index);return `<article class="cast-card">${roleAvatar(role,'',index)}<h3>${c.name}</h3><small>${roleName(role)}</small><details class="history-role"><summary>${tr('চরিত্রের কথা','Character history')}</summary><p>${c.history}</p>${c.source?`<a href="${c.source}" target="_blank" rel="noopener">${tr('সূত্র','Source')} ↗</a>`:''}</details></article>`;}).join('');}
